        align-self: center;
    }
    .header-mobile-marquee-schedule-wrap,
    .header-mobile-marquee-search-wrap {
        flex-shrink: 0;
        display: flex !important;
        align-items: center !important;
        align-self: center !important;
        margin-top: 0 !important;
        margin-bottom: 0 !important;
        position: relative;
        z-index: 4;
    }
    /*
     * Tombol jadwal + search di marquee: ikut palette header atas (variabel :root dari templateStyle / tema).
     * Tombol biru default (.football-schedule-open-btn) tetap untuk banner/desktop di luar marquee.
     */
    .header-mobile__marquee .football-schedule-open-btn {
        margin: 0;
        vertical-align: middle;
        
        
        border: 1px solid rgba(255, 255, 255, 0.26);
        box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
    }
    @supports (border-color: color-mix(in srgb, red, blue)) {
        .header-mobile__marquee .football-schedule-open-btn {
            border-color: color-mix(in srgb, var(--header-text, #ffffff) 30%, transparent);
        }
    }
    .header-mobile__marquee .football-schedule-open-btn:hover,
    .header-mobile__marquee .football-schedule-open-btn:focus {
        background-color: var(--header-color, var(--title-color, #0d47a1));
        color: var(--header-text, var(--primary-text, #ffffff)) !important;
        filter: brightness(1.07);
    }
    @supports (border-color: color-mix(in srgb, red, blue)) {
        .header-mobile__marquee .football-schedule-open-btn:hover,
        .header-mobile__marquee .football-schedule-open-btn:focus {
            border-color: color-mix(in srgb, var(--header-text, #ffffff) 45%, transparent);
        }
    }
    /* Tema memakai .header-mobile__marquee i { background: secondary; } untuk ikon siaran; reset untuk ikon di tombol */
    .header-mobile__marquee .football-schedule-open-btn i {
        font-size: 0.85em;
        vertical-align: -0.05em;
        background: none !important;
        background-color: transparent !important;
        padding: 0 !important;
        color: inherit !important;
        box-shadow: none;
    }

    .btn.luxury-icon-btn {
        background: none !important;
        border: none !important;
        padding: 0 !important;
        box-shadow: none !important;
        cursor: pointer;
        outline: none;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transition: all 0.4s cubic-bezier(0.25, 1, 0.5, 1);
        filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.4));
        animation: luxuryBreathe 3s ease-in-out infinite;
    }

    .btn.luxury-icon-btn img {
        width: 95px; 
        height: auto;
        display: block;
    }
    @media (max-width: 768px) {
    .btn.luxury-icon-btn img {
        width: 80px;
    }
}

    .btn.luxury-icon-btn:hover {
        transform: scale(1.06) translateY(-2px);
        filter: drop-shadow(0 0 12px rgba(255, 215, 0, 0.65)) 
                drop-shadow(0 0 25px rgba(255, 255, 255, 0.2)) !important;
    }
    .btn.luxury-icon-btn:active {
        transform: scale(0.96) translateY(0);
        filter: drop-shadow(0 2px 4px rgba(255, 215, 0, 0.4)) !important;
    }

    @keyframes luxuryBreathe {
        0%, 100% {
            transform: scale(1);
            filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.4));
        }
        50% {
            transform: scale(1.03);
            filter: drop-shadow(0 4px 12px rgba(255, 215, 0, 0.3));
        }
    }
</style>


