        if (typeof jQuery === 'undefined' || !jQuery.fn.modal) {
            showLoginAlert();
            return;
        }
        var $m = jQuery('#footballScheduleModal');
        if (!$m.length) {
            showLoginAlert();
            return;
        }
        if ($m.hasClass('show')) {
            $m.one('hidden.bs.modal', showLoginAlert);
            $m.modal('hide');
            setTimeout(showLoginAlert, 450);
        } else {
            showLoginAlert();
        }
    };

    var modal = document.getElementById('footballScheduleModal');
    if (!modal) return;

    /** Sync aria-hidden before focus moves (avoids Chrome “Blocked aria-hidden…” when open). */
    function syncAriaHiddenWhileOpen() {
        modal.setAttribute('aria-hidden', 'false');
    }
    function syncAriaHiddenWhileClosed() {
        modal.setAttribute('aria-hidden', 'true');
    }
    if (typeof jQuery !== 'undefined') {
        jQuery(modal).on('show.bs.modal', syncAriaHiddenWhileOpen);
        jQuery(modal).on('hidden.bs.modal', syncAriaHiddenWhileClosed);
    } else {
        modal.addEventListener('show.bs.modal', syncAriaHiddenWhileOpen);
        modal.addEventListener('hidden.bs.modal', syncAriaHiddenWhileClosed);
    }
})();
