<script>
/* Shared deposit/withdraw amount bounds (data-deposit-min / data-deposit-max on validated input). */
(function () {
    if ($.validator.methods.depositAmountMin) {
        return;
    }

    function parseDepositBound($el, attr, fallback) {
        var raw = $el.attr(attr);
        var n = parseFloat(raw, 10);
        return isNaN(n) ? fallback : n;
    }

    function parseAmountValue(value) {
        return parseFloat(String(value).replace(/,/g, ''), 10);
    }

    $.validator.addMethod('depositAmountMin', function (value, element) {
        if (this.optional(element)) {
            return true;
        }
        var min = parseDepositBound($(element), 'data-deposit-min', 0);
        var num = parseAmountValue(value);
        return !isNaN(num) && num >= min;
    }, "Deposit tidak boleh kurang dari minimal.");

    $.validator.addMethod('depositAmountMax', function (value, element) {
        if (this.optional(element)) {
            return true;
        }
        var max = parseDepositBound($(element), 'data-deposit-max', 999000000);
        var num = parseAmountValue(value);
        return !isNaN(num) && num <= max;
    }, "Deposit tidak boleh melebihi maksimal.");

    window.setDepositAmountBounds = function ($input, min, max) {
        if (!$input || !$input.length) {
            return;
        }
        if (min != null && min !== '') {
            $input.attr('data-deposit-min', min);
        }
        if (max != null && max !== '') {
            $input.attr('data-deposit-max', max);
        }
        $input.removeAttr('min').removeAttr('max');
    };
})();
</script>
