<script>
    const getQueryParameter = (param) => new URLSearchParams(document.location.search.substring(1)).get(param);
    const TRACKING_PARAM_KEYS = ['opera_click_id', 'fbclid', 'fb_clickid', 'ttclid', 'tt_clickid'];
    const TRACKING_PARAM_EXCLUDED_PATHS = ['/transaction', '/profile', '/memo', '/history', '/member/logout', '/bonus'];
    let trackingClickHandlerBound = false;

    const parseUrl = (href) => {
        try {
            return new URL(href, window.location.origin);
        } catch (e) {
            return null;
        }
    };

    const shouldAppendTrackingParam = (href) => {
        if (!href || href.startsWith('#')) {
            return false;
        }
        const url = parseUrl(href);
        if (!url) {
            return false;
        }
        if (url.origin !== window.location.origin) {
            return true;
        }
        const path = (url.pathname.replace(/\/$/, '') || '/');
        return !TRACKING_PARAM_EXCLUDED_PATHS.some((excluded) => path === excluded || path.startsWith(excluded + '/'));
    };

    const appendTrackingParamsToUrl = (href, keys) => {
        const url = parseUrl(href);
        if (!url || !shouldAppendTrackingParam(href)) {
            return href;
        }
        keys.forEach((key) => {
            const val = sessionStorage.getItem(key);
            if (val && !url.searchParams.has(key)) {
                url.searchParams.set(key, val);
            }
        });
        if (href.startsWith('/') || !href.includes('://')) {
            return url.pathname + url.search + url.hash;
        }
        return url.href;
    };

    const applyTrackingParamsToLinks = () => {
        $('a[href]').each(function () {
            const href = $(this).attr('href');
            if (!href || href === 'javascript:;' || href.startsWith('#')) {
                return;
            }
            const updated = appendTrackingParamsToUrl(href, TRACKING_PARAM_KEYS);
            if (updated !== href) {
                $(this).attr('href', updated);
            }
        });
    };

    const syncTrackingParamsFromUrl = () => {
        TRACKING_PARAM_KEYS.forEach((key) => {
            const fromUrl = getQueryParameter(key);
            if (fromUrl !== null) {
                sessionStorage.setItem(key, fromUrl);
            }
        });
    };

    const initTrackingParams = () => {
        syncTrackingParamsFromUrl();
        TRACKING_PARAM_KEYS.forEach((key) => {
            const value = sessionStorage.getItem(key);
            if (value !== null) {
                $('#register-form').append(`<input type="hidden" name="${key}" value="${value}">`);
            }
        });
        applyTrackingParamsToLinks();
        if (trackingClickHandlerBound) {
            return;
        }
        trackingClickHandlerBound = true;
        $(document).on('click.trackingParams', '[onclick]', function (e) {
            const onclick = $(this).attr('onclick');
            const match = onclick && onclick.match(/window\.location\.href\s*=\s*['"]([^'"]+)['"]/);
            if (!match) {
                return;
            }
            const url = match[1];
            if (!shouldAppendTrackingParam(url)) {
                return;
            }
            e.preventDefault();
            e.stopImmediatePropagation();
            window.location.href = appendTrackingParamsToUrl(url, TRACKING_PARAM_KEYS);
        });
    };

    initTrackingParams();

    // Handle ads parameter
    if (getQueryParameter('ads') !== null) {
        $.ajax({
            type: "POST",
            url: "https://irvehn5w4.mpomustarena.pro/userCheck",
            data: {
                _token: "nLTg6jjhyyv5xvaAEISWHrBCMfGAsdDWHWqXnJl5",
                adNumber: getQueryParameter('ads')
            },
            success: function (response) {
                return console.log("adsHit: " + response)
            }
        });
    }
    
    // Handle affiliate code and trackId parameters
    var affCode = getQueryParameter('affCode');
    var trackId = getQueryParameter('trackId');
    if (affCode !== null || trackId !== null) {
        var data = {
            _token: "nLTg6jjhyyv5xvaAEISWHrBCMfGAsdDWHWqXnJl5"
        };
        if (affCode !== null) {
            data.affCode = affCode;
        }
        if (trackId !== null) {
            data.trackId = trackId;
        }
        $.ajax({
            type: "POST",
            url: "https://irvehn5w4.mpomustarena.pro/userCheck",
            data: data,
            success: function (response) {
                return console.log("affCode/trackId: " + JSON.stringify(response))
            }
        });
    }
</script>

