                        clearInterval(timer);
                        Swal.close()
                    }
                    $('.swal2-html-container').html(displayText.replace(/#1/, `<strong>${timeClose}</strong>`));
                }, 1000);
                // Always force redirect to home after the error toast duration,
                // even if the Swal promise doesn't resolve for some reason.
                setTimeout(function () {
