<script>
(function () {
    function getFootballScheduleModal() {
        return document.getElementById('footballScheduleModal');
    }

    function footballScheduleEscapeHtml(s) {
        var d = document.createElement('div');
        d.textContent = s;
        return d.innerHTML;
    }

    function footballScheduleLoadingHtml(mount) {
        var msg = mount.getAttribute('data-loading-msg') || '';
        return '<p class="football-schedule-loading mb-0 text-center py-4">' +
            '<i class="fas fa-circle-notch fa-spin mr-2" aria-hidden="true"></i>' +
            '<span>' + footballScheduleEscapeHtml(msg) + '</span></p>';
    }

    function footballScheduleErrorHtml(mount, messageOverride) {
        var msg = (messageOverride != null && messageOverride !== '')
            ? messageOverride
            : (mount.getAttribute('data-error-msg') || '');
        return '<p class="football-schedule-empty mb-0 text-center py-4">' + footballScheduleEscapeHtml(msg) + '</p>';
    }

    function bindFootballScheduleControls(modal) {
        var select = document.getElementById('footballScheduleTimezoneSelect');
        var matchCodeFilter = document.getElementById('footballScheduleMatchCodeFilter');
        var searchInput = document.getElementById('footballScheduleSearchInput');
        if (!select) {
            return;
        }

        function formatKickoffCells() {
            var tz = select.value;
            if (!tz) {
                return;
            }
            var lang = (document.documentElement.lang || 'en').replace('_', '-');
            modal.querySelectorAll('.football-schedule-time-cell[data-ts]').forEach(function (td) {
                var raw = td.getAttribute('data-ts');
                var ts = parseInt(raw, 10);
                if (!ts) {
                    return;
                }
                try {
                    td.textContent = new Intl.DateTimeFormat(lang, {
                        day: '2-digit',
                        month: 'short',
                        year: 'numeric',
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: false,
                        timeZone: tz
                    }).format(new Date(ts * 1000));
                } catch (e) {
                    td.textContent = '—';
                }
            });
        }

        function applyRowFilters() {
            if (!matchCodeFilter || !searchInput) {
                return;
            }
            var code = matchCodeFilter.value;
            var q = (searchInput.value || '').trim().toLowerCase();

            modal.querySelectorAll('.football-schedule-group-tbody').forEach(function (tb) {
                var gCode = tb.getAttribute('data-match-code') || '';
                var codeOk = !code || gCode === code;

                if (!codeOk) {
                    tb.style.display = 'none';
                    return;
                }

                var matchRows = tb.querySelectorAll('.football-schedule-match-row');
                var headRow = tb.querySelector('.football-schedule-group-head-row');
                var visibleCount = 0;

                matchRows.forEach(function (tr) {
                    var hay = (tr.getAttribute('data-search-haystack') || '').toLowerCase();
                    var searchOk = !q || hay.indexOf(q) !== -1;
                    tr.style.display = searchOk ? '' : 'none';
                    if (searchOk) {
                        visibleCount++;
                    }
                });

                var show = visibleCount > 0 || !q;
                tb.style.display = show ? '' : 'none';
                if (headRow) {
                    headRow.style.display = show ? '' : 'none';
                }
            });
        }

        select.addEventListener('change', formatKickoffCells);
        select.addEventListener('input', formatKickoffCells);
        if (matchCodeFilter) {
            matchCodeFilter.addEventListener('change', applyRowFilters);
            matchCodeFilter.addEventListener('input', applyRowFilters);
        }
        if (searchInput) {
            searchInput.addEventListener('input', applyRowFilters);
            searchInput.addEventListener('search', applyRowFilters);
        }
        formatKickoffCells();
        applyRowFilters();
    }

    function loadFootballScheduleFromApi() {
        var modal = getFootballScheduleModal();
        var mount = document.getElementById('footballScheduleAjaxMount');
        var toolbarMount = document.getElementById('footballScheduleToolbarMount');
        if (!modal || !mount) {
            return;
        }
        var fetchUrl = mount.getAttribute('data-fetch-url');
        var csrf = mount.getAttribute('data-csrf-token');
        if (!fetchUrl || !csrf) {
            return;
        }
        if (toolbarMount) {
            toolbarMount.innerHTML = '';
        }
        mount.innerHTML = footballScheduleLoadingHtml(mount);

        fetch(fetchUrl, {
            method: 'POST',
            credentials: 'same-origin',
            headers: {
                'X-Requested-With': 'XMLHttpRequest',
                'Accept': 'application/json',
                'Content-Type': 'application/x-www-form-urlencoded',
                'X-CSRF-TOKEN': csrf
            },
            body: '_token=' + encodeURIComponent(csrf)
        })
            .then(function (res) {
                if (res.status === 429) {
                    if (toolbarMount) {
                        toolbarMount.innerHTML = '';
                    }
                    mount.innerHTML = footballScheduleErrorHtml(mount, mount.getAttribute('data-too-many-msg'));
                    return null;
                }
                if (!res.ok) {
                    throw new Error('HTTP ' + res.status);
                }
                return res.json();
            })
            .then(function (data) {
                if (data === null) {
                    return;
                }
                if (toolbarMount && typeof data.toolbar === 'string') {
                    toolbarMount.innerHTML = data.toolbar;
                }
                mount.innerHTML = typeof data.list === 'string' ? data.list : footballScheduleErrorHtml(mount);
                bindFootballScheduleControls(modal);
            })
            .catch(function () {
                if (toolbarMount) {
                    toolbarMount.innerHTML = '';
                }
                mount.innerHTML = footballScheduleErrorHtml(mount);
            });
    }

    function bindFootballScheduleModalAjax() {
        if (typeof jQuery === 'undefined' || !jQuery.fn.modal) {
            setTimeout(bindFootballScheduleModalAjax, 0);
            return;
        }
        var modal = getFootballScheduleModal();
        if (!modal) {
            return;
        }
        jQuery(modal)
            .off('show.bs.modal.footballScheduleAjax')
            .on('show.bs.modal.footballScheduleAjax', loadFootballScheduleFromApi);
    }

    bindFootballScheduleModalAjax();
})();
</script>
<script>
  function handler(e) {
    e.stopPropagation();
    e.preventDefault();
  }
    
  $('#pageLoadingBar').hide()
  window.onpopstate = function() {
    let path = window.location.pathname;
    routeNav(path);
  }
  
  function setQueryParameter(param, value) {
    $('a[href]').attr('href', function(index, href) {
      if (isValidUrl(href) && href != 'javascript:;') {
        let url = new URL(href)
        url.searchParams.set(param, value)
        return url
      } else {
        return href
      }
    });
  }
  const k = 'opera_click_id'
  if (sessionStorage.getItem(k) !== null) {
    setQueryParameter(k, sessionStorage.getItem(k))
  } else {
    if (getQueryParameter(k) !== null) {
        setQueryParameter(k, getQueryParameter(k))
        sessionStorage.setItem(k, getQueryParameter(k))
    }
  }

  function routeNav(path) {
    let urlPar = ''
    $.each(sessionStorage, function (key, val) { 
        if ($.inArray(key, ['opera_click_id', 'fbclid', 'fb_clickid', 'ttclid', 'tt_clickid']) !== -1) {
            urlPar += (urlPar.includes('?') ? '&' : '?') + key + '=' + val;
        }
    });
    path += urlPar
    const pathOnly = path.split('?')[0];
    if (pathOnly === window.location.pathname) return;
    history.pushState(null, null, path);
    let url = "https://irvehn5w4.mpomustarena.pro" + pathOnly;
    if (pathOnly === '/') {
        window.location.replace("https://irvehn5w4.mpomustarena.pro")
        return false;
    }
    $(".header-form>a").removeClass('active')
    let elem = document.getElementById("pageLoadingBar");
    let width = 1;
    $.ajax({
      type: "GET",
      url: url,
      headers: {
        'X-Requested-With': 'XMLHttpRequest'
      },
      beforeSend: () => {
        $('#pageLoadingBar').show()
        let id = setInterval(frame, 100);
        function frame() {
          if (width >= 100) {
            clearInterval(id);
          } else {
            width++;
            elem.style.width = width + '%';
          }
        }
      },
      success: function (page) {
        width = 100;
        elem.style.width = width + '%';
        $("main[id=main-route]").empty().append(page);
        $("title").text($("#title-seo").text());
        const script = $("scope-script").html()
        $("scope-script").remove()
        setTimeout(() => {
          $("html, body").animate({ scrollTop: "0" }, 1000);
          $('#pageLoadingBar').hide()
          elem.style.width = '1%';
          $("custom-script").empty().append(script);
          filterGameSelection('all')
        }, 500);
      }
    });
  }
    
  window.addEventListener("popstate", (event) => {
    location.reload();
  });
</script>
